#include <vector>
using namespace std;

vector<int> add(vector<int> a, vector<int> b) {
    int carry = 0;
    vector<int> c;
    int n = max(a.size(), b.size());
    for (int i = 0; i < n || carry; i++) {
        if (i < a.size()) carry += a[i];
        if (i < b.size()) carry += b[i];
        c.push_back(carry % 10);
        carry /= 10;
    }
    return c;
}

vector<int> sub(vector<int> a, vector<int> b) {
    int carry = 0;
    vector<int> c;
    int n = a.size();
    for (int i = 0; i < n; i++) {
        carry += a[i] - (i < b.size() ? b[i] : 0);
        c.push_back((carry + 10) % 10);
        carry = carry < 0 ? -1 : 0;
    }
    while (c.size() > 1 && c.back() == 0) c.pop_back();
    return c;
}

vector<int> mul(vector<int> a, int b) {
    long long carry = 0;
    vector<int> c;
    for (int i = 0; i < a.size() || carry; i++) {
        if (i < a.size()) carry += a[i] * b;
        c.push_back(carry % 10);
        carry /= 10;
    }
    return c;
}

vector<int> mul(vector<int> a, vector<int> b) {
    vector<int> c(a.size() + b.size(), 0);
    for (int i = 0; i < a.size(); i++) {
        for (int j = 0; j < b.size(); j++) {
            c[i + j] += a[i] * b[j];
        }
    }
    int carry = 0;
    for (int i = 0; i < c.size(); i++) {
        carry += c[i];
        c[i] = carry % 10;
        carry /= 10;
    }
    while (c.size() > 1 && c.back() == 0) c.pop_back();
    return c;
}

int main() {
    vector<int> a = {3, 2, 1};
    vector<int> b = {5, 4};

    auto c = add(a, b);
    for (int i = c.size() - 1; i >= 0; i--) cout << c[i];
    cout << endl;

    auto d = mul(a, b);
    for (int i = d.size() - 1; i >= 0; i--) cout << d[i];
    cout << endl;

    return 0;
}

#include <iostream>
#include <complex>
#include <cmath>
#include <vector>
#include <algorithm>
using namespace std;

const double PI = acos(-1.0);
typedef complex<double> cd;

void fft(vector<cd>& a, bool invert) {
    int n = a.size();
    for (int i = 1, j = 0; i < n; i++) {
        int bit = n >> 1;
        for (; j & bit; bit >>= 1) j ^= bit;
        j ^= bit;
        if (i < j) swap(a[i], a[j]);
    }
    for (int len = 2; len <= n; len <<= 1) {
        double ang = 2 * PI / len * (invert ? -1 : 1);
        cd wlen(cos(ang), sin(ang));
        for (int i = 0; i < n; i += len) {
            cd w(1);
            for (int j = 0; j < len / 2; j++) {
                cd u = a[i + j], v = a[i + j + len / 2] * w;
                a[i + j] = u + v;
                a[i + j + len / 2] = u - v;
                w *= wlen;
            }
        }
    }
    if (invert) {
        for (cd& x : a) x /= n;
    }
}

vector<int> multiply(vector<int> a, vector<int> b) {
    vector<cd> fa(a.begin(), a.end()), fb(b.begin(), b.end());
    int n = 1;
    while (n < a.size() + b.size()) n <<= 1;
    fa.resize(n); fb.resize(n);
    fft(fa, false); fft(fb, false);
    for (int i = 0; i < n; i++) fa[i] *= fb[i];
    fft(fa, true);
    vector<int> result(n);
    for (int i = 0; i < n; i++) result[i] = round(fa[i].real());
    return result;
}

int main() {
    vector<int> a = {1, 2, 3};
    vector<int> b = {4, 5, 6};

    auto c = multiply(a, b);
    for (int x : c) cout << x << " ";
    cout << endl;

    return 0;
}

#include <iostream>
using namespace std;

const int MAXB = 60;
long long b[MAXB + 5];

void insert(long long x) {
    for (int i = MAXB; i >= 0; i--) {
        if (!(x >> i)) continue;
        if (b[i]) x ^= b[i];
        else { b[i] = x; return; }
    }
}

long long getMax() {
    long long ans = 0;
    for (int i = MAXB; i >= 0; i--) {
        ans = max(ans, ans ^ b[i]);
    }
    return ans;
}

long long getMin() {
    for (int i = 0; i <= MAXB; i++) {
        if (b[i]) return b[i];
    }
    return 0;
}

bool check(long long x) {
    for (int i = MAXB; i >= 0; i--) {
        x = min(x, x ^ b[i]);
    }
    return x == 0;
}

int main() {
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) {
        long long x;
        cin >> x;
        insert(x);
    }

    cout << "Max XOR: " << getMax() << endl;
    cout << "Min XOR: " << getMin() << endl;

    long long x;
    cin >> x;
    cout << "Can represent " << x << ": " << check(x) << endl;

    return 0;
}

#include <iostream>
#include <algorithm>
using namespace std;

const int N = 100005;

struct Node {
    int x, y, z, id;
} a[N], tmp[N];

int ans[N], bit[N];

int lowbit(int x) {
    return x & -x;
}

void add(int x, int v) {
    for (; x < N; x += lowbit(x)) bit[x] += v;
}

int query(int x) {
    int res = 0;
    for (; x > 0; x -= lowbit(x)) res += bit[x];
    return res;
}

bool cmpx(const Node& a, const Node& b) {
    return a.x < b.x || (a.x == b.x && a.y < b.y);
}

bool cmpy(const Node& a, const Node& b) {
    return a.y < b.y;
}

void cdq(int l, int r) {
    if (l == r) return;
    int mid = (l + r) >> 1;
    cdq(l, mid);

    sort(a + l, a + mid + 1, cmpy);
    sort(a + mid + 1, a + r + 1, cmpy);

    for (int i = mid + 1, j = l; i <= r; i++) {
        while (j <= mid && a[j].y <= a[i].y) {
            add(a[j].z, 1);
            j++;
        }
        ans[a[i].id] += query(a[i].z);
    }

    for (int i = l; i <= mid; i++) {
        add(a[i].z, -1);
    }

    cdq(mid + 1, r);
}

int main() {
    int n;
    cin >> n;
    for (int i = 1; i <= n; i++) {
        cin >> a[i].x >> a[i].y >> a[i].z;
        a[i].id = i;
    }

    sort(a + 1, a + n + 1, cmpx);
    cdq(1, n);

    for (int i = 1; i <= n; i++) {
        cout << ans[i] << endl;
    }

    return 0;
}

