void solve(int l, int r, int ql, int qr) {
    if (ql > qr) return;
    if (l == r) {
        for (int i = ql; i <= qr; i++) {
            if (q[i].type == 2) {
                ans[q[i].id] = l;
            }
        }
        return;
    }

    int mid = (l + r) >> 1;
    int cnt1 = 0, cnt2 = 0;

    for (int i = ql; i <= qr; i++) {
        if (q[i].type == 1) {
            if (q[i].l <= mid) {
                add(q[i].id, q[i].k);
                q1[++cnt1] = q[i];
            } else {
                q2[++cnt2] = q[i];
            }
        } else {
            int sum = query(q[i].r) - query(q[i].l - 1);
            if (sum >= q[i].k) {
                q1[++cnt1] = q[i];
            } else {
                q[i].k -= sum;
                q2[++cnt2] = q[i];
            }
        }
    }

    for (int i = 1; i <= cnt1; i++) {
        if (q1[i].type == 1) {
            add(q1[i].id, -q1[i].k);
        }
    }

    for (int i = 1; i <= cnt1; i++) q[ql + i - 1] = q1[i];
    for (int i = 1; i <= cnt2; i++) q[ql + cnt1 + i - 1] = q2[i];

    solve(l, mid, ql, ql + cnt1 - 1);
    solve(mid + 1, r, ql + cnt1, qr);
}

